export const empty=()=>({version:1,materials:[],suppliers:[],purchases:[],entries:[],proposals:[],employees:[],steps:[],audit:[],quotes:[]});
export class SessionRepository{constructor(storage=globalThis.localStorage){this.storage=storage;this.data=empty()}load(){this.storage?.removeItem('rr-elvira-v1');this.data=empty();return structuredClone(this.data)}validate(s){if(!s||s.version!==1||Object.keys(empty()).some(k=>k!=='version'&&!Array.isArray(s[k])))throw Error('Backup incompatível');return s}save(s){this.data=structuredClone(this.validate(s))}}
export {SessionRepository as LocalRepository};
